"""Generated by the NL to Flow Diagram Encoder Pipeline."""

numlist = [6, 7, 9, 4, 66, 8, 34, 5, 2]

print(numlist)

n = (len(numlist) - 1)

for i in range(0, n):
    for j in range(0, (n - i)):
        if (numlist[j] > numlist[(j + 1)]):
            temp = numlist[j]
            numlist[j] = numlist[(j + 1)]
            numlist[(j + 1)] = temp

